/* Standalone, no API calls. Everything mutable is an in-memory design demonstration. */
(() => {
  const directions = [
    ['秩序工作台', '极简任务工具 · 先处理待测变化，再查看历史事实'],
    ['编辑期刊', '报刊式阅读 · 用文章与注释呈现测试事实'],
    ['信号控制塔', '工业信息墙 · 高对比状态与高密度操作'],
    ['协作画布', '柔和流程板 · 按阶段和任务在空间里工作'],
    ['系统图谱', '工程地图 · 用节点与矩阵追踪证据关系'],
    ['运行手账', '纸质档案感 · 按时间复盘每次交接']
  ];
  const palettes = [ ['jade','松绿','#207659'], ['clay','赤陶','#ac512f'], ['marine','海蓝','#126e86'] ];
  const views = [ ['dashboard','总览'],['active','当前测试'],['runs','Runs'],['scenarios','场景'],['git','Git'],['settings','配置'] ];
  const stages = ['Main · 规划','Runner','Reviewer','Main · 最终汇总'];
  const settingsTabs = [ ['provider','模型服务'],['agents','Agent 模型'],['browser','浏览器'],['oss','Evidence'],['github','GitHub'],['environment','测试环境'],['automation','自动触发'],['local','本地运行'],['checks','检查总览'],['transfer','导入导出'],['security','安全'] ];
  const scenarios = [
    { id:'AUTH-SESSION-DEMO', name:'用户会话恢复', status:'approved', tags:['core','module:认证'], purpose:'验证已登录用户刷新受保护页面后仍保持有效会话。', steps:['用专用非生产测试账号登录。','刷新受保护页面。','检查页面仍允许访问且身份状态保持。'], expectation:'登录会话持续有效；不以当前代码实现反推期望。', history:'DEMO-RUN-00 · passed' },
    { id:'ACCOUNT-CREATE-DEMO', name:'注册与测试数据清理', status:'approved', tags:['core','flow:注册'], purpose:'验证创建合成账号、删除并核验不存在的完整流程。', steps:['使用 Run 前缀创建合成账号。','检查用户可见的创建反馈。','删除本次数据，并查询确认不存在。'], expectation:'注册符合需求；清理必须有可读取的工具或截图证据。', history:'DEMO-RUN-00 · passed' },
    { id:'PROFILE-SAVE-DEMO', name:'资料保存与回读', status:'draft', tags:['module:账户'], purpose:'验证资料修改后重新打开仍显示已保存值。', steps:['进入非生产资料页面。','修改合成数据并保存。','重新打开并核对值。'], expectation:'保存后的值能够回读；有偏差时留存证据。', history:'尚无正式 Run' },
    { id:'HISTORY-REVIEW-DEMO', name:'历史报告索引', status:'approved', tags:['module:报告'], purpose:'验证运行结束后可从 Git 索引中查询当前 Run 报告。', steps:['等待示意 Run 归档。','在运行记录中打开正式报告。','比对 Run ID 与固定 target。'], expectation:'报告属于当前 Run，不能覆盖历史报告。', history:'DEMO-RUN-00 · passed' }
  ];
  const initialRuns = [
    { id:'DEMO-RUN-01', title:'会话恢复与注册流程', result:'running', phase:'Runner', target:'示例提交 A', archive:'等待执行', trigger:'manual-current-head', time:'09:32', detail:'演示中的当前 Run；并非真实测试记录。' },
    { id:'DEMO-RUN-00', title:'核心业务回归', result:'passed', phase:'completed', target:'示例提交 B', archive:'报告已归档', trigger:'automatic-head', time:'昨天 16:12', detail:'演示历史报告：已审核且已归档。' },
    { id:'DEMO-RUN-XX', title:'外部依赖检查', result:'blocked', phase:'completed', target:'示例提交 C', archive:'报告已归档', trigger:'manual-current-head', time:'昨天 11:08', detail:'依赖不满足时 blocked，不推进上次完成目标。' },
    { id:'DEMO-RUN-ARCHIVE', title:'归档重试示意', result:'passed', phase:'completed', target:'示例提交 D', archive:'归档失败', trigger:'manual-current-head', time:'前天 15:23', detail:'测试结论已成立；归档失败单独标记，允许幂等重试。' }
  ];
  const memory = { get(key,fallback){try{return localStorage.getItem(key)||fallback}catch{return fallback}}, set(key,value){try{localStorage.setItem(key,value)}catch{}} };
  const savedStyle=Number(memory.get('lw-explore-v2-style','1'));
  const savedPalette=memory.get('lw-explore-v2-palette','jade');
  const state = {
    style: savedStyle>=1&&savedStyle<=6?savedStyle:1,
    palette: palettes.some(p=>p[0]===savedPalette)?savedPalette:'jade',
    view:'dashboard', sample:'idle', stage:1, hasCompletedDemo:false, settingTab:'provider', scenarioStatus:'all', scenarioQuery:'', selectedScenario:scenarios[0].id,
    runStatus:'all', runQuery:'', runs:initialRuns.map(x=>({...x})), queue:[],
    checks:{}, toast:'', dialog:null, runTab:'summary', runId:'DEMO-RUN-01', draftRequest:'', repoSource:'', automation:false
  };
  const $ = id => document.getElementById(id);
  const escape = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const running = () => state.sample!=='idle' && state.stage<4;
  function syncDemoRun(){const run=state.runs.find(x=>x.id==='DEMO-RUN-01');if(!run)return;const finished=state.sample==='idle';run.result=finished?'passed':'running';run.phase=finished?'completed':stages[state.stage];run.archive=finished?'报告已归档':'等待执行'}
  const stale = () => state.sample==='stale';
  const progress = () => running()?`${Math.min(state.stage===1?2:4,4)} / 4`:'0 / 0';
  const current = () => running() ? stages[state.stage] : '空闲';
  const badge = (text,kind='neutral') => `<span class="tag ${kind}">${escape(text)}</span>`;
  const label = (text) => `<span class="micro">${escape(text)}</span>`;
  const demoNotice = () => `<div class="notice ${stale()?'warn':''}">${stale()?'依赖状态演示：读取可能陈旧。保留最近一次事实，不把旧缓存显示为最新成功。':'演示数据 · 此页面与真实罗网完全隔离；提交、检查、合并和归档都只改变浏览器内的预览状态。'}</div>`;
  const stageTrack = () => `<div class="stage-track" aria-label="四阶段角色交接">${stages.map((name,i)=>`<div class="${!running()?'':i<state.stage?'done':i===state.stage?'current':''}"><b>0${i+1}</b>${name}</div>`).join('')}</div>`;
  const nav = () => `<nav class="app-nav" aria-label="控制台演示导航">${views.map(([key,title],i)=>`<button type="button" class="${state.view===key?'active':''}" aria-current="${state.view===key?'page':'false'}" data-nav="${key}"><span class="nav-index">0${i+1}</span>${title}</button>`).join('')}</nav>`;
  const status = () => running()?badge(`${current()} · 执行中`,''):badge('当前空闲','good');
  const deps = () => `<div class="list-row"><div><strong>GitHub / 场景分支</strong><small>场景测试事实与报告</small></div>${badge('正常','good')}</div><div class="list-row"><div><strong>Provider / Pi Session</strong><small>三组配置 · 四阶段会话</small></div>${badge(stale()?'缓存陈旧':'正常',stale()?'warn':'good')}</div><div class="list-row"><div><strong>Playwright / OSS</strong><small>浏览器和证据存储</small></div>${badge(stale()?'需复核':'正常',stale()?'warn':'good')}</div>`;
  const recent = (count=3) => state.runs.slice(0,count).map(run=>`<div class="list-row"><div><strong class="mono">${escape(run.id)}</strong><small>${escape(run.title)}</small></div><button class="link-button" type="button" data-run="${escape(run.id)}">${escape(run.result)} ↗</button></div>`).join('');
  const metric = (title,value,note) => `<div class="metric"><span class="micro">${escape(title)}</span><strong>${escape(value)}</strong><small>${escape(note)}</small></div>`;
  const head = (eyebrow,title,subtitle,buttons='') => `<header class="view-header"><div>${label(eyebrow)}<h1>${title}</h1><p>${subtitle}</p></div><div class="row">${buttons}</div></header>`;
  const panel = (title,content,action='') => `<section class="panel"><div class="section-heading"><h2>${title}</h2>${action}</div>${content}</section>`;
  const action = (title,attrs='',primary=false) => `<button type="button" class="btn ${primary?'primary':''}" ${attrs}>${title}</button>`;
  const scope = `<span class="mono">scenario-testing</span> · target <strong>示例提交 A</strong>`;
  function renderHome1(){return `<div class="view home-1">${head('01 / DAILY OPERATIONS','测试工作台','先处理当前执行，再查看下一步。',action('＋ 发起测试','data-open="request"',true))}${demoNotice()}<div class="cols section-space"><section class="panel feature"><div class="between"><div>${label('CURRENT RUN')}<h2> ${running()?'正在验证用户会话恢复':'当前没有正在执行的 Run'}</h2></div>${status()}</div><div><div class="feature-count">${progress()}</div><p class="muted">${running()?'场景进度 · AUTH-SESSION-DEMO':'Run 队列等待新的测试请求'}</p><div class="progress section-space"><i style="width:${running()?state.stage===1?50:100:0}%"></i></div></div>${stageTrack()}<button type="button" class="link-button" data-nav="active">查看当前测试 →</button></section><div class="stack">${panel('固定目标',`${label('IMMUTABLE TARGET')}<h3>scenario-testing</h3><p class="muted small">Run 在调度时固定目标 commit；不会用移动中的 HEAD 冒充测试事实。</p><p class="section-space">${badge('示例提交 A')}</p>`, `<button type="button" class="link-button" data-nav="git">打开 Git →</button>`)}${panel('下一个交接',`<p class="small">${running()?'Runner 完成后由 Reviewer 在独立 Session 中审核证据。':'等待新的人工请求或自动测试请求。'}</p>`)}</div></div><div class="quad section-space">${metric('等待队列',String(state.queue.length).padStart(2,'0'),'FIFO 顺序执行')}${metric('长期场景','04','Git 索引中的示意场景')}${metric('场景进度',progress(),'当前 Run 上报')}${metric('归档状态','就绪','报告归属当前 Run')}</div><div class="cols section-space">${panel('最近 Runs',recent(),`<button class="link-button" data-nav="runs">全部 Runs →</button>`)}${panel('依赖健康',deps(),`<button class="link-button" data-nav="settings">检查配置 →</button>`)}</div></div>`}
  function renderHome2(){return `<div class="view home-2"><div class="masthead"><div>${label('FIELD NOTES / TEST OPERATIONS')}<h1 class="hero-title">把每一次测试，<br>写成可信的事实。</h1></div><p class="muted">固定目标、执行、独立审核和正式归档，在一页上有明确来路。信息是主角，不用卡片替代阅读。</p></div><div class="mast-index"><span>ISSUE 01 / OPERATIONS</span><span>${scope}</span><span>演示状态 / 非实时</span></div>${stale()?`<div class="section-space">${demoNotice()}</div>`:''}<div class="cols section-space-lg"><section><div class="feature-line"><span class="lead-number">${running()?'02':'—'}</span>${label('CURRENT CHAPTER')}<h2>${running()?'正在验证用户会话恢复':'今天没有正在执行的 Run'}</h2><p class="muted">${running()?'Runner 执行中。报告尚未通过独立审核；当前观察不能当作最终结论。':'可以查看历史 Run，或提交演示请求。'}</p><div class="progress section-space"><i style="width:${running()?50:0}%"></i></div><span class="fine">${progress()} · ${current()}</span></div><div class="between section-space-lg"><h2>运行记录</h2><button class="link-button" data-nav="runs">阅读全部 →</button></div>${recent()}<div class="section-space-lg">${action('发起一份新的测试请求','data-open="request"',true)}</div></section><aside><span class="micro">THE SIGNAL</span><div style="font:600 67px var(--serif);color:var(--accent);margin:10px 0">${progress()}</div><p class="muted small">已完成场景 / 计划场景</p><hr class="sep"><h2>四次交接</h2>${stageTrack()}<hr class="sep"><h2>系统边界</h2><div class="list-row"><strong>Git 是长期事实源</strong><span class="mono">01</span></div><div class="list-row"><strong>Runner 不负责审核</strong><span class="mono">02</span></div><div class="list-row"><strong>清理失败单独告警</strong><span class="mono">03</span></div></aside></div></div>`}
  function renderHome3(){return `<div class="view home-3">${head('SYSTEM / OPERATIONS MONITOR','测试运行控制塔','高密度状态格、活动、队列与依赖。演示数据不代表实时监控。',action('＋ 请求','data-open="request"',true))}${stale()?demoNotice():''}<div class="telemetry"><div>${label('01 / ACTIVE PHASE')}<b>${current()}</b><span class="fine">AUTH-SESSION-DEMO</span></div><div>${label('02 / SCENARIO PROGRESS')}<b>${progress()}</b><span class="fine">Runner 进度事实</span></div><div>${label('03 / FIFO QUEUE')}<b>${String(state.queue.length).padStart(2,'0')}</b><span class="fine">当前待处理请求</span></div><div>${label('04 / BRANCH INDEX')}<b>READY</b><span class="fine">scenario-testing / 示例提交</span></div></div><div class="control-grid"><section class="panel"><div class="section-heading"><h2>当前执行 / DEMO-RUN-01</h2>${status()}</div>${stageTrack()}<hr class="sep">${label('SANITIZED ACTIVITY LOG')}<div class="log-row"><span class="mono muted">09:41</span><span>${running()?'Runner 开始场景 AUTH-SESSION-DEMO':'当前没有活跃场景'}</span>${badge(running()?'执行中':'空闲')}</div><div class="log-row"><span class="mono muted">09:39</span><span>计划已固定：目标提交与场景顺序</span>${badge('完成','good')}</div><div class="log-row"><span class="mono muted">09:32</span><span>Main · 规划形成执行计划</span>${badge('完成','good')}</div><div class="section-space">${action('进入当前测试','data-nav="active"')}</div></section><section class="panel"><div class="section-heading"><h2>DEPENDENCIES</h2><button class="link-button" data-nav="settings">查看配置 →</button></div>${deps()}<hr class="sep"><div class="section-heading"><h2>RECENT RUNS</h2><button class="link-button" data-nav="runs">全部 →</button></div>${recent(2)}</section></div><div class="triplet section-space">${metric('仓库事实','GIT','场景与正式报告')}${metric('审核证据','OSS','截图状态不等于结论')}${metric('后台归档','FIFO','收尾失败单独告警')}</div></div>`}
  function renderHome4(){const cards=[['Main · 规划','已交接','理解变化、选场景、固定目标','plan.md'],['Runner',running()?progress():'空闲','顺序执行、记录原始观察与清理声明','execution.md'],['Reviewer','等待审核','读取固定期望和受控证据，独立判断','review.md'],['Main · 最终汇总','等待交接','按审核结论聚合并写正式报告','report.md']];return `<div class="view home-4"><div class="flow-intro"><div>${label('THE HANDOFF STUDIO')}<h1 class="hero-title">一条可追溯的<br>测试链路。</h1><p class="muted">这里按工作交接而不是表格栏目组织界面。</p></div>${action('＋ 发起演示请求','data-open="request"',true)}</div>${stale()?demoNotice():''}<div class="flow-board">${cards.map(([title,flag,desc,file],i)=>`<section class="lane ${running()?i<state.stage?'done':i===state.stage?'current':'':''}">${label(`0${i+1} / ${i<state.stage?'COMPLETE':i===state.stage?'CURRENT':'NEXT'}`)}<h3>${title}</h3><span class="fine">SESSION 0${i+1}</span><div class="ticket">${badge(flag,i<state.stage?'good':i===state.stage?'':'warn')}<h4>${desc}</h4><p>工件交接 → <span class="mono">${file}</span></p></div></section>`).join('')}</div><div class="cols section-space-lg">${panel('请求队列',`${state.queue.map(q=>`<div class="list-row"><strong>${escape(q.id)}</strong><span>${escape(q.status)}</span></div>`).join('')}<p class="muted small section-space">人工 merge-source 与普通人工 Run 都先进入同一 FIFO。</p>`, `<button class="link-button" data-nav="git">查看队列 →</button>`)}${panel('待复核项目',`${deps()}<p class="muted small section-space">清理证据要经过独立核验；Runner 声明不是完成事实。</p>`, `<button class="link-button" data-nav="active">查看执行 →</button>`)}</div></div>`}
  function renderHome5(){const cell=(kind,title,detail)=>`<div class="cell ${kind}" role="cell"><strong>${title}</strong><span>${detail}</span></div>`;return `<div class="view home-5"><div class="atlas-heading"><div>${label('THE EVIDENCE ATLAS')}<h1 class="hero-title">把事实之间的关系，<br>摊开来看。</h1></div><div><p class="muted">横向是角色，纵向是测试事实。空格不冒充已验证结果，而是明确标识未到达的交接。</p><div class="section-space">${action('查看当前证据','data-nav="active"')}</div></div></div>${stale()?`<div class="section-space">${demoNotice()}</div>`:''}<div class="matrix" role="table" aria-label="测试事实与角色关系矩阵"><div class="axis corner" role="columnheader">FACT / ROLE</div>${stages.map((x)=>`<div class="axis" role="columnheader">${x}</div>`).join('')}<div class="axis" role="rowheader">固定目标</div>${cell('done','已固定','示例提交 A')}${cell('done','已接收','固定 target')}${cell('','待读取','独立审核')}${cell('','待汇总','不重定目标')}<div class="axis" role="rowheader">场景执行</div>${cell('done','已选择','4 个示意场景')}${cell('current',progress(),'AUTH-SESSION-DEMO')}${cell('','待审核','原始证据')}${cell('','待汇总','passed / failed / blocked')}<div class="axis" role="rowheader">交接工件</div>${cell('done','plan.md','已交接')}${cell('current','execution.md','演示进行中')}${cell('','review.md','尚未形成')}${cell('','report.md','尚未形成')}<div class="axis" role="rowheader">清理核验</div>${cell('','非生产','数据范围约束')}${cell('','删除 / 声明','不等于核验')}${cell('','证据读取','独立确认')}${cell('','Harness 收尾','单独告警')}</div><div class="atlas-bottom">${panel('聚焦 / 当前场景',`<h2>${running()?'正在验证用户会话恢复':'当前没有执行中的场景'}</h2><p class="muted small">AUTH-SESSION-DEMO · 进度 ${progress()}。页面状态不是最终测试结论。</p><div class="progress section-space"><i style="width:${running()?50:0}%"></i></div>`, `<button class="link-button" data-nav="active">打开执行 →</button>`)}${panel('Run / 索引',recent(3), `<button class="link-button" data-nav="runs">全部 →</button>`)}</div></div>`}
  function renderHome6(){return `<div class="view home-6"><div class="journal-cover"><div>${label('RUN JOURNAL / DEMO-RUN-01')}<h1 class="hero-title">记录过程，<br>不是只写结果。</h1><p class="muted">从不可变目标提交开始，沿着计划、执行、证据与审核，把一次运行的来路留下来。</p></div><div class="cover-number"><strong>${progress()}</strong><span class="muted small">示意场景已完成 · ${current()}</span></div></div><div class="journal-strip"><span>项目 / 示例仓库</span><span>分支 / scenario-testing</span><span>target / 示例提交 A</span><span>状态 / ${stale()?'缓存陈旧':current()}</span></div><div class="journal-body"><section><div class="between"><h2>运行纪事</h2><button class="link-button" data-run="DEMO-RUN-01">查看 Run 摘要 ↗</button></div><p class="muted small">按演示时间排列。真实活动不包含模型隐藏推理。</p><div class="timeline section-space"><div class="timeline-entry current"><span class="fine">09:41 / 现在</span><h3>${running()?'Runner 正在验证用户会话恢复':'当前没有正在执行的 Run'}</h3><p>场景 AUTH-SESSION-DEMO · 完成进度 ${progress()}。</p></div><div class="timeline-entry done"><span class="fine">09:39 / 交接</span><h3>计划已固定并交给 Runner</h3><p>Main · 规划明确场景顺序和证据要求。</p></div><div class="timeline-entry done"><span class="fine">09:32 / 起点</span><h3>从场景测试分支固定目标提交</h3><p>Run 使用不可变 target，不追逐移动中的 HEAD。</p></div><div class="timeline-entry"><span class="fine">接下来</span><h3>Reviewer 独立审核</h3><p>先读原始场景和受控证据，再看 Runner 草稿。</p></div><div class="timeline-entry"><span class="fine">最终</span><h3>报告归档与 Harness 收尾</h3><p>清理失败单独告警，不追改测试结论。</p></div></div>${action('浏览全部运行记录','data-nav="runs"')}</section><aside>${label('RUN FACTS')}<h2>当前事实</h2><div class="list-row"><strong>角色</strong><span>${current()}</span></div><div class="list-row"><strong>场景</strong><span>${progress()}</span></div><div class="list-row"><strong>队列</strong><span>FIFO</span></div><h2 class="section-space-lg">依赖</h2>${deps()}<h2 class="section-space-lg">下一步</h2><p class="muted small">进入当前测试页查看角色交接、活动、工件和阶段演示。</p><div class="section-space">${action('进入当前测试','data-nav="active"',true)}</div></aside></div></div>`}
  function renderDashboard(){return [renderHome1,renderHome2,renderHome3,renderHome4,renderHome5,renderHome6][state.style-1]()}
  function renderActive(){const activity=[['09:41',`${running()?'Runner 正在执行 AUTH-SESSION-DEMO':'当前无活跃场景'}`,running()?'current':''],['09:39','Main · 规划已交接固定 target 与执行顺序','done'],['09:32','DEMO-RUN-01 进入 FIFO 队列','done']];return `<div class="view">${head('LIVE / ACTIVE RUN','当前测试',`演示 Run：DEMO-RUN-01 · ${scope}`,`${status()} ${action('推进演示阶段','data-next-stage',true)}`)}${demoNotice()}<div class="quad section-space">${metric('负责角色',current(),'四个隔离 Session')}${metric('场景进度',progress(),'当前场景由 Runner 上报')}${metric('base commit','示例提交 B','上一次已完成目标')}${metric('target commit','示例提交 A','本 Run 固定 checkout')}</div><div class="panel section-space-lg">${label('SESSION HANDOFF / FOUR STAGES')}<div class="section-space">${stageTrack()}</div></div><div class="detail-shell section-space"><section class="panel"><div class="section-heading"><h2>脱敏活动</h2><span class="fine">示意时间 · 不展示模型隐藏推理</span></div><div class="timeline">${activity.map(([t,msg,kind])=>`<div class="timeline-entry ${kind}"><span class="fine">${t}</span><h3>${msg}</h3><p>${kind==='current'?'当前状态并非最终结论。':'活动由当前 Run 状态提供。'}</p></div>`).join('')}</div></section><aside class="stack">${panel('当前场景',`<h3>${running()?'用户会话恢复':'暂无正在执行的场景'}</h3><p class="muted small">${running()?'AUTH-SESSION-DEMO · 已完成 '+progress():'当前 Run 为空闲状态'}</p><div class="progress section-space"><i style="width:${running()?state.stage===1?50:100:0}%"></i></div>`)}${panel('Run 工件',`<div class="artifact"><span class="mono">plan.md</span>${badge('已交接','good')}</div><div class="artifact"><span class="mono">execution.md</span>${badge(running()?'写入中':'待执行')}</div><div class="artifact"><span class="mono">review.md</span>${badge(state.stage>2?'示意已形成':'等待审核')}</div><div class="artifact"><span class="mono">report.md</span>${badge(state.stage>3?'示意已形成':'等待汇总')}</div><p class="muted tiny section-space">截图 / 日志只有在真实 Run 中才有真实证据；此处不伪造图片。</p>`, `<button class="link-button" data-run="DEMO-RUN-01">详情 →</button>`)}</aside></div></div>`}
  function runResult(run){return badge(run.result,run.result==='passed'?'good':run.result==='blocked'?'warn':run.result==='failed'?'bad':'')}
  function renderRuns(){const visible=state.runs.filter(r=>(state.runStatus==='all'||r.result===state.runStatus)&&(`${r.id} ${r.title} ${r.target}`.toLowerCase().includes(state.runQuery.toLowerCase())));let cards=visible.map(r=>`<article class="record"><div><h3>${escape(r.title)} <span class="mono muted">${escape(r.id)}</span></h3><small>${escape(r.trigger)} · target ${escape(r.target)} · ${escape(r.time)}</small></div>${runResult(r)}<button class="link-button" type="button" data-run="${escape(r.id)}">查看详情 ↗</button></article>`).join('');return `<div class="view">${head('RUN STORE / READ MODEL','运行记录','包含通过、阻塞、执行中与归档状态；这些都是演示用 Run。',action('发起测试请求','data-open="request"',true))}${demoNotice()}<div class="filters section-space"><label class="field">搜索 Run 或 target<input id="run-query" value="${escape(state.runQuery)}" placeholder="Run ID / 标题 / target" autocomplete="off"></label><label class="field">结果<select id="run-filter"><option value="all">全部结果</option><option value="running">执行中</option><option value="passed">passed</option><option value="failed">failed</option><option value="blocked">blocked</option></select></label><span class="fine">${visible.length} 条示意记录</span></div><div class="run-records">${cards||'<div class="empty">没有符合条件的 Run。试试清空筛选。</div>'}</div><div class="cols section-space-lg">${panel('结果如何形成',`<p class="muted small">Runner 记录观察与草稿；Reviewer 独立审核；最终 Main 只根据工件和审核写报告。blocked 不推进已完成目标。</p>`)}${panel('归档与历史',`<p class="muted small">正式报告以目标仓库 Git 为长期事实源；数据库只用于网站索引与详细 Run 记录。</p>`)}</div></div>`}
  function scenarioCard(s){return `<article class="scenario-card"><div>${label(s.id)}<h3>${s.name}</h3><p>${s.purpose}</p><div class="row wrap">${s.tags.map(t=>badge(t)).join('')}</div></div><footer><span>${badge(s.status,s.status==='approved'?'good':'warn')}</span><button type="button" class="link-button" data-scenario="${s.id}">阅读场景 →</button></footer></article>`}
  function renderScenarios(){const filtered=scenarios.filter(s=>(state.scenarioStatus==='all'||s.status===state.scenarioStatus)&&(`${s.id} ${s.name} ${s.purpose} ${s.tags.join(' ')}`.toLowerCase().includes(state.scenarioQuery.toLowerCase())));const selected=scenarios.find(s=>s.id===state.selectedScenario)||scenarios[0];return `<div class="view">${head('SCENARIO LIBRARY / GIT INDEX','长期场景','场景为目标仓库 Git 中的 Markdown 资产；这里是演示样例。',badge('只读预览'))}${demoNotice()}<div class="filters section-space"><label class="field">搜索场景<input id="scenario-query" value="${escape(state.scenarioQuery)}" placeholder="名称、ID、标签" autocomplete="off"></label><label class="field">状态<select id="scenario-filter"><option value="all">全部状态</option><option value="approved">approved</option><option value="draft">draft</option><option value="deprecated">deprecated</option></select></label><span class="fine">已显示 ${filtered.length} / ${scenarios.length}</span></div><div class="scenario-layout"><div class="scenario-grid">${filtered.map(scenarioCard).join('')||'<div class="empty">没有匹配的场景。可清除筛选查看全部。</div>'}</div><aside class="panel scenario-detail">${label('SELECTED SCENARIO')}<h2>${selected.name}</h2><div class="row wrap">${badge(selected.id)}${badge(selected.status,selected.status==='approved'?'good':'warn')}</div><p class="muted small section-space">${selected.purpose}</p><hr class="sep">${label('STEPS / 示例步骤')}<ol>${selected.steps.map(x=>`<li>${x}</li>`).join('')}</ol>${label('EXPECTED / 期望')}<p class="small section-space">${selected.expectation}</p><hr class="sep"><span class="fine">历史：${selected.history}</span><p class="muted tiny section-space">演示页不修改场景；真实变更由 Main 的受限 patch 与 Git 归档处理。</p></aside></div></div>`}
  function renderGit(){return `<div class="view">${head('REPOSITORY / FIXED BRANCH','Git 与请求队列',`单一目标仓库 · ${scope}`,action('演示同步索引','data-sync'))}${demoNotice()}<div class="quad section-space">${metric('目标仓库','示例仓库','非真实配置')}${metric('场景分支','scenario-testing','单一正式测试分支')}${metric('远端 HEAD','示例提交 A','只作分支事实')}${metric('本 Run target','示例提交 A','固定后不可变')}</div><div class="cols section-space-lg"><section class="panel"><div class="section-heading"><h2>提交路径</h2><span class="fine">演示数据 / 未连接 GitHub</span></div><div class="git-graph"><div class="git-commit"><span class="mono">示例提交 A</span><strong>合并可测试变更</strong><small>scenario-testing / 最新示意 HEAD</small></div><div class="git-commit"><span class="mono">示例提交 B</span><strong>上次已完成测试目标</strong><small>Run DEMO-RUN-00 / passed</small></div><div class="git-commit"><span class="mono">示例提交 C</span><strong>历史基线</strong><small>正式报告已归档</small></div></div><button class="btn" type="button" data-nav="runs">查看关联 Runs</button></section><section class="panel"><div class="section-heading"><h2>人工 merge-source</h2>${badge('进入 FIFO')}</div><p class="muted small">branch / tag / SHA 需先合并到场景测试分支，经过 prepared/resolved 固定后才创建 Run。这里仅模拟入队。</p><form id="merge-form" class="stack section-space"><label class="field">来源 ref<input name="sourceRef" required maxlength="80" placeholder="例如 feature/demo" autocomplete="off"></label><label class="check"><input type="checkbox" name="initialization"> 首次初始化请求（仅场景分支不存在时）</label><button class="btn primary" type="submit">模拟排队 merge-source</button></form></section></div><div class="cols section-space"><section class="panel"><div class="section-heading"><h2>顺序请求队列</h2><span class="fine">${state.queue.length} 项</span></div>${state.queue.map(q=>`<div class="list-row"><div><strong>${escape(q.id)}</strong><small>${escape(q.source)}</small></div>${badge(q.status,q.status==='排队中'?'':'good')}</div>`).join('')||'<div class="empty">队列为空。</div>'}</section>${panel('索引与归档',`<div class="list-row"><strong>场景索引</strong>${badge('示例 4 项','good')}</div><div class="list-row"><strong>正式报告</strong>${badge('示例历史可读','good')}</div><p class="muted small section-space">Git 临时不可用时显示陈旧缓存，不把缓存当最新同步。</p>`)}</div></div>`}
  function settingFields(){switch(state.settingTab){
    case 'provider':return `<div class="form-grid"><label class="field">Provider<select><option>示例 Provider</option><option>自定义 Provider（演示）</option></select></label><label class="field">Base URL<input placeholder="https://provider.example.test/v1" type="url"></label><label class="field">Provider API Key<input type="password" disabled placeholder="原型不接收或保存 Secret"><small>正式系统仅经 Secret Store 保存</small></label></div><p class="notice section-space">测试连接必须使用已保存配置；原型不发请求，也不声称模型可用。</p>`;
    case 'agents':return `<div class="config-cards">${[['Main','规划与最终汇总 / 文本'],['Runner','场景执行 / 文本'],['Reviewer','证据与截图审核 / 视觉模型']].map(([name,role])=>`<div class="panel"><h3>${name}</h3><p class="muted small">${role}</p><label class="field section-space">模型<select><option>请选择 · 演示</option><option>文本候选（演示）</option><option>视觉候选（演示）</option></select></label><label class="field section-space">Thinking<select><option>medium</option><option>low</option><option>high</option></select></label>${name==='Reviewer'?'<p class="notice warn section-space">视觉场景须使用支持图像输入的模型。</p>':''}</div>`).join('')}</div><p class="muted small section-space">三组 Agent 配置；正常 Run 的 Main 规划和最终汇总是两个独立 Session。</p>`;
    case 'browser':return `<div class="form-grid"><label class="field">浏览器<select><option>Chromium</option><option>Firefox</option><option>WebKit</option></select></label><label class="field">MCP 超时（毫秒）<input type="number" value="30000" min="100" max="300000"></label></div><label class="check section-space"><input type="checkbox" checked> 启用 Playwright MCP（仅演示开关）</label><p class="notice section-space">正式连接检查需真实 MCP 握手；此处不会启动浏览器。</p>`;
    case 'oss':return `<div class="form-grid"><label class="field">Endpoint<input type="url" placeholder="https://storage.example.test"></label><label class="field">Bucket<input placeholder="private-evidence"></label><label class="field">Object Prefix<input placeholder="luowang/demo/"></label><label class="field">凭据<input type="password" disabled placeholder="原型不接收或保存 Secret"></label></div><p class="notice section-space">正式环境用私有 prefix 验证 put/get/head/delete；此处无对象操作。</p>`;
    case 'github':return `<div class="form-grid"><label class="field">目标仓库<input value="https://github.com/example/trusted-fixture" readonly></label><label class="field">场景分支<input value="scenario-testing" readonly></label><label class="field">场景模式<select><option>review-all</option><option>add-only</option><option>autonomous</option></select></label><label class="field">GitHub Token<input type="password" disabled placeholder="原型不接收或保存 Secret"></label></div><p class="notice section-space">GitHub 综合检查需逐项确认仓库读取、分支写入前提、PR、Issue；无法无副作用验证时应显示 unknown。</p>`;
    case 'environment':return `<div class="form-grid"><label class="field">非生产 Base URL<input type="url" placeholder="https://staging.example.test"></label><label class="field">环境说明<input placeholder="仅使用合成数据"></label><label class="field">测试账号<input type="password" disabled placeholder="原型不接收账号"></label><label class="field">测试密码<input type="password" disabled placeholder="原型不接收或保存 Secret"></label></div><p class="notice warn section-space">生产数据、真实用户与未授权外部副作用均不可用于测试。</p>`;
    case 'automation':return `<div class="stack"><label class="check"><input type="checkbox" id="automation-toggle" ${state.automation?'checked':''}> 新 commit 自动测试（演示开关）</label><label class="field">检查间隔（分钟）<input type="number" min="5" value="5" ${state.automation?'':'disabled'}><small>只在出现可测试提交时入队；不是每 5 分钟无条件运行</small></label><label class="field">Cron（UTC）<input placeholder="留空，不启用" autocomplete="off"></label><p class="notice">模拟切换只影响当前浏览器，不修改服务调度器。</p></div>`;
    case 'local':return `<div class="form-grid"><label class="field">界面语言<select><option>简体中文</option><option>English（演示）</option></select></label><label class="field">保留天数<input type="number" min="0" value="14"></label><label class="field">Repository 目录<input value="/workspace/repository" readonly></label><label class="field">Report 目录<input value="/workspace/reports" readonly></label></div><p class="notice section-space">目录仅用于说明布局，不读取本机文件。</p>`;
    case 'transfer':return `<div class="stack"><p class="muted small">YAML 只包含普通配置，不含 Secret、检查结果或 Run。这里可下载一份纯示意的安全样例，也可体验预览校验。</p><label class="field">待导入 YAML（仅演示）<textarea id="yaml-preview" rows="6" spellcheck="false">version: 1\nharness:\n  language: zh-CN\nrepository:\n  scenarioBranch: scenario-testing</textarea><small>若包含 secrets 字段，示意校验会拒绝。不会导入或保存。</small></label><div class="row wrap">${action('下载无 Secret 示例 YAML','data-export-demo')}${action('模拟导入校验','data-validate-yaml',true)}</div></div>`;
    case 'security':return `<div class="form-grid"><label class="field">当前管理员密码<input type="password" disabled placeholder="原型不接收密码"></label><label class="field">新密码<input type="password" disabled placeholder="原型不接收密码"></label></div><p class="notice warn section-space">真实密码修改会使所有管理会话失效。演示原型不提供密码输入或提交，以免误存真实凭据。</p>`;
    default:return `<p class="muted">选择一个配置模块。</p>`;
  }}
  function renderSettings(){const tab=state.settingTab;const currentTab=settingsTabs.find(x=>x[0]===tab)?.[1]||'模型服务';const checks=['Provider / 三角色','Playwright MCP','OSS Evidence','GitHub 综合','非生产环境'];return `<div class="view">${head('CONFIGURATION / CONTROLLED INPUT','配置与连通性','分组件保存、测试和反馈；本原型不读取、接收或保存真实 Secret。',badge('仅演示'))}${demoNotice()}<nav class="setting-nav section-space" aria-label="配置分类">${settingsTabs.map(([id,title])=>`<button type="button" class="${id===tab?'active':''}" data-setting="${id}">${title}</button>`).join('')}</nav><div class="settings-layout"><section class="panel"><div class="section-heading"><div>${label('MODULE / '+tab.toUpperCase())}<h2>${currentTab}</h2></div>${tab!=='checks'?badge('未配置 / 演示') :badge('最近结果 / 演示')}</div>${tab==='checks'?`<p class="muted small">正式系统从保存的配置执行检查；未配置与未启用不算通过。</p><div class="checks section-space">${checks.map(c=>`<div class="check-row"><span>${c}<small>未发出真实请求</small></span>${badge(state.checks[c]||'未检查',state.checks[c]?'warn':'neutral')}</div>`).join('')}</div><div class="section-space">${action('演示“测试全部”','data-check="all"',true)}</div>`:`<form class="stack" id="settings-demo-form" autocomplete="off">${settingFields()}${['transfer','security'].includes(tab)?'':`<div class="row wrap section-space-lg">${action('模拟保存','data-save="'+tab+'"')}${action('模拟保存并测试','data-check="'+tab+'"',true)}</div><p class="muted tiny section-space">“模拟”动作只显示交互反馈，不验证外部依赖或保存输入值。</p>`}</form>`}</section><aside class="stack">${panel('配置原则',`<div class="list-row"><strong>Secret Store</strong>${badge('无明文回显','good')}</div><div class="list-row"><strong>测试连接</strong>${badge('保存后执行')}</div><div class="list-row"><strong>Reviewer</strong>${badge('需要视觉','warn')}</div>`)}${panel('本地与账号安全',`<p class="muted small">管理员初始密码只从部署环境初始化；本演示没有登录、密码修改或 Secret 写入入口。</p><p class="muted small section-space">普通配置 YAML 不应包含 Secret；可在「导入导出」查看无 Secret 演示样例。</p>`)}${panel('依赖状态',deps())}</aside></div></div>`}
  function appShell(content){if(state.style===1)return `<div class="prototype style-1"><aside class="side"><div class="brand-name">罗网 <span>LuoWang</span></div><span class="micro">SCENARIO TESTING HARNESS</span>${nav()}<div class="side-bottom"><button type="button" class="btn primary" style="margin-bottom:14px" data-open="request">＋ 演示请求</button><br><span class="good"><span class="dot"></span>Gateway / SQLite 正常</span><p class="muted">单仓库 · 顺序执行</p></div></aside><div class="app-content">${content}</div></div>`;
    const extra=state.style===2?'<span class="fine">VOL. 01 · TEST OPERATIONS</span>':state.style===3?'<span class="fine">GATEWAY ● ONLINE / DEMO</span>':state.style===5?'<span class="fine">GRID 06 / FIXED TARGET</span>':state.style===6?'<span class="fine">RUN JOURNAL / DEMO</span>':'';
    return `<div class="prototype style-${state.style}"><header class="app-top"><div class="brand-name">罗网 <span>LuoWang</span></div>${nav()}<button class="btn global-request" type="button" data-open="request">＋ 演示请求</button>${extra?`<span class="app-meta">${extra}</span>`:''}</header><div class="app-content">${content}</div></div>`;
  }
  function render(){document.body.dataset.style=String(state.style);document.body.dataset.palette=state.palette;
    $('explore-name').textContent=`${String(state.style).padStart(2,'0')} · ${directions[state.style-1][0]}`;
    $('explore-description').textContent=directions[state.style-1][1];
    $('style-switch').innerHTML=directions.map(([name],i)=>`<button type="button" data-style="${i+1}" aria-pressed="${state.style===i+1}">${String(i+1).padStart(2,'0')} ${name}</button>`).join('');
    $('palette-switch').innerHTML=palettes.map(([key,name,color])=>`<button type="button" data-palette="${key}" aria-label="${name}配色" aria-pressed="${state.palette===key}"><i class="swatch" style="--swatch:${color}"></i>${name}</button>`).join('');
    const content=window.LWPages.render(state.style,state.view,{state,scenarios,settingsTabs,stages,escape,badge,label,demoNotice,stageTrack,nav,status,deps,recent,metric,head,panel,action,scope,running,stale,progress,current,runResult,settingFields});
    $('prototype').innerHTML=appShell(content);
    if($('run-filter')) $('run-filter').value=state.runStatus;
    if($('scenario-filter')) $('scenario-filter').value=state.scenarioStatus;
  }
  let toastTimer;function toast(msg){const node=$('toast');node.textContent=msg;node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.hidden=true,4000)}
  let previousFocus=null;
  function openDialog(type,id){previousFocus=document.activeElement;state.dialog=type;state.runId=id||state.runId;state.runTab='summary';drawDialog();$('overlay').hidden=false;const target=$('overlay').querySelector('button');target?.focus()}
  function closeDialog(){state.dialog=null;$('overlay').hidden=true;previousFocus?.focus()}
  function drawDialog(){if(!state.dialog)return;const title=state.dialog==='request'?'发起演示测试请求':state.dialog==='run'?'Run 详情 · '+state.runId:'演示交互';$('dialog-title').textContent=title;
    if(state.dialog==='request'){$('dialog-body').innerHTML=`<p class="notice">此表单只在浏览器内模拟一条 FIFO 请求；不调用真实 API、不创建 Run，也不会修改 Git。</p><form id="request-form" class="stack section-space"><label class="field">测试请求<textarea name="request" rows="3" required minlength="4" maxlength="220" placeholder="描述希望验证的当前场景测试分支行为"></textarea></label><p class="muted small">目标提交在真实系统轮到调度时才固定；这里不允许指定任意 target。</p><div class="row wrap">${action('取消','data-close-dialog') }<button class="btn primary" type="submit">模拟加入队列</button></div></form>`;return}
    const run=state.runs.find(x=>x.id===state.runId)||state.runs[0]; const tabs=[['summary','摘要'],['plan','计划'],['execution','执行'],['review','审核'],['report','报告'],['evidence','证据']];
    const text={summary:`<div class="stack"><div class="list-row"><strong>Run ID</strong><span class="mono">${escape(run.id)}</span></div><div class="list-row"><strong>结果</strong>${runResult(run)}</div><div class="list-row"><strong>固定 target</strong><span>${escape(run.target)}</span></div><div class="list-row"><strong>触发来源</strong><span class="mono">${escape(run.trigger)}</span></div><div class="list-row"><strong>归档</strong><span>${escape(run.archive)}</span></div><p class="notice">${escape(run.detail)}</p></div>`,plan:`<pre># plan.md · 演示摘录\n目标：${escape(run.target)}\n选择：AUTH-SESSION-DEMO、ACCOUNT-CREATE-DEMO\n理由：覆盖当前变更和核心路径\n浏览器执行：需要（由 Main 显式声明）</pre>`,execution:`<pre># execution.md · 演示摘录\nRunner 按场景顺序执行，记录观察与证据引用。\n临时测试数据只使用 Run 前缀。\nRunner 的清理声明不等于已独立核验。</pre>`,review:`<pre># review.md · 演示摘录\nReviewer 独立读取固定期望及受控证据，\n最后才审核 Runner 草稿。\n截图示意未提供真实图像，不冒充已看图。</pre>`,report:`<pre># report.md · 演示摘录\n结果：${escape(run.result)}\ntarget：${escape(run.target)}\n仅示意排版；正式报告须由真实 Run 形成并归档。</pre>`,evidence:`<div class="empty">未提供真实截图或日志。此处故意不伪造可点击的 OSS 证据。</div>`};
    $('dialog-body').innerHTML=`<p class="muted small">所有详情内容均是原型示意，不是正式 Run 工件。</p><div class="tabs" role="tablist" aria-label="Run 详情栏目">${tabs.map(([key,name])=>`<button type="button" role="tab" aria-selected="${state.runTab===key}" class="${state.runTab===key?'active':''}" data-run-tab="${key}">${name}</button>`).join('')}</div><div role="tabpanel">${text[state.runTab]}</div><div class="section-space">${run.archive==='归档失败'?action('模拟重试归档','data-retry="'+escape(run.id)+'"'):''}</div>`;
  }
  function setView(view){if(!views.some(x=>x[0]===view))return;state.view=view;render();window.scrollTo({top:0,behavior:'smooth'})}
  function handleClick(event){const e=event.target.closest('button');if(!e)return;
    if(e.dataset.style){state.style=Number(e.dataset.style);memory.set('lw-explore-v2-style',String(state.style));render();return}
    if(e.dataset.palette){state.palette=e.dataset.palette;memory.set('lw-explore-v2-palette',state.palette);render();return}
    if(e.dataset.nav){setView(e.dataset.nav);return}
    if(e.dataset.setting){state.settingTab=e.dataset.setting;render();return}
    if(e.dataset.scenario){state.selectedScenario=e.dataset.scenario;render();return}
    if(e.dataset.run){openDialog('run',e.dataset.run);return}
    if(e.dataset.open){openDialog(e.dataset.open);return}
    if(e.dataset.runTab){state.runTab=e.dataset.runTab;drawDialog();return}
    if(e.hasAttribute('data-close-dialog')){closeDialog();return}
    if(e.hasAttribute('data-close-tweaks')){toggleTweaks(false);return}
    if(e.hasAttribute('data-next-stage')){if(state.sample==='idle'){state.sample='running';state.stage=1;$('sample-mode').value='running'}else if(state.stage<3){state.stage++;toast('已推进演示阶段；不对应真实 Run。')}else{state.sample='idle';state.stage=1;state.hasCompletedDemo=true;$('sample-mode').value='idle';toast('演示 Run 已结束；没有执行或归档真实任务。')}syncDemoRun();render();return}
    if(e.hasAttribute('data-sync')){toast('已演示同步反馈：没有访问 GitHub，也没有更新真实索引。');return}
    if(e.hasAttribute('data-save')){toast('已演示保存反馈：草稿未发送，Secret 未保存。');return}
    if(e.hasAttribute('data-check')){if(e.dataset.check==='all'){['Provider / 三角色','Playwright MCP','OSS Evidence','GitHub 综合','非生产环境'].forEach(k=>state.checks[k]='演示反馈')}else{const k=({provider:'Provider / 三角色',agents:'Provider / 三角色',browser:'Playwright MCP',oss:'OSS Evidence',github:'GitHub 综合',environment:'非生产环境',automation:'自动触发'})[e.dataset.check];if(k)state.checks[k]='演示反馈'}render();toast('仅展示检查交互；未连接外部服务，不能视为检查通过。');return}
    if(e.hasAttribute('data-export-demo')){const yaml='version: 1\nharness:\n  language: zh-CN\nrepository:\n  scenarioBranch: scenario-testing\n';const url=URL.createObjectURL(new Blob([yaml],{type:'application/yaml'}));const link=document.createElement('a');link.href=url;link.download='luowang-config-demo.yaml';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已下载无 Secret 演示 YAML；未读取真实配置。');return}
    if(e.hasAttribute('data-validate-yaml')){const text=$('yaml-preview')?.value||'';if(/(^|\n)\s*secrets\s*:/im.test(text)){toast('演示校验拒绝：配置 YAML 不允许包含 secrets 字段。')}else if(!/^version:\s*1\s*$/m.test(text)){toast('演示校验拒绝：仅接受 version: 1 的样例。')}else{toast('演示格式检查通过；未导入、未保存，也未执行正式 schema 校验。')}return}
    if(e.hasAttribute('data-retry')){toast('模拟归档重试反馈：未进行 Git 写入。');return}
  }
  function handleChange(event){const e=event.target;if(e.id==='sample-mode'){state.sample=e.value;state.stage=1;state.hasCompletedDemo=false;syncDemoRun();render()}if(e.id==='density-toggle'){document.body.classList.toggle('compact',e.checked)}if(e.id==='run-filter'){state.runStatus=e.value;render()}if(e.id==='scenario-filter'){state.scenarioStatus=e.value;render()}if(e.id==='automation-toggle'){state.automation=e.checked;render()}}
  function handleInput(event){const e=event.target;if(e.id==='run-query'){state.runQuery=e.value;updateListKeepingFocus('run-query')}if(e.id==='scenario-query'){state.scenarioQuery=e.value;updateListKeepingFocus('scenario-query')}}
  function updateListKeepingFocus(id){const pos=document.activeElement.selectionStart;render();const field=$(id);field?.focus();field?.setSelectionRange(pos,pos)}
  function handleSubmit(event){const form=event.target;if(form.id==='settings-demo-form'){event.preventDefault();toast('原型未保存配置；请使用演示按钮查看反馈。');return}if(form.id==='request-form'){event.preventDefault();const text=String(new FormData(form).get('request')||'').trim();if(text.length<4)return;const id=`Q-DEMO-${String(state.queue.length+1).padStart(2,'0')}`;state.queue.unshift({id,source:text.slice(0,80),status:'排队中'});closeDialog();render();toast(`${id} 已加入演示队列；未提交真实测试请求。`)}
    if(form.id==='merge-form'){event.preventDefault();const data=new FormData(form),source=String(data.get('sourceRef')||'').trim();if(!source)return;const id=`Q-DEMO-${String(state.queue.length+1).padStart(2,'0')}`;state.queue.unshift({id,source:`${source}${data.has('initialization')?' / initialization':''}`,status:'排队中'});render();toast(`${id} 已模拟入队；未执行 merge、push 或建分支。`)}}
  function toggleTweaks(force){const panel=$('tweaks');panel.hidden=force===undefined?!panel.hidden:!force;$('tweak-toggle').setAttribute('aria-expanded',String(!panel.hidden))}
  document.addEventListener('click',handleClick);
  document.addEventListener('change',handleChange);
  document.addEventListener('input',handleInput);
  document.addEventListener('submit',handleSubmit);
  $('tweak-toggle').addEventListener('click',()=>toggleTweaks());
  $('overlay').addEventListener('click',event=>{if(event.target===$('overlay'))closeDialog()});
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.dialog){closeDialog();return}if(event.key==='Tab'&&state.dialog){const items=[...$('overlay').querySelectorAll('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled])')];if(!items.length)return;const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});
  render();
})();
